using Astraea.Domain;
using Microsoft.EntityFrameworkCore;
namespace Astraea.Infrastructure;
public sealed class AstraeaDbContext(DbContextOptions<AstraeaDbContext> options) : DbContext(options)
{
 public DbSet<User> Users=>Set<User>(); public DbSet<MentorLearner> MentorLearners=>Set<MentorLearner>(); public DbSet<Skill> Skills=>Set<Skill>(); public DbSet<SkillPrerequisite> SkillPrerequisites=>Set<SkillPrerequisite>(); public DbSet<StudyLog> StudyLogs=>Set<StudyLog>(); public DbSet<PracticeSignal> PracticeSignals=>Set<PracticeSignal>(); public DbSet<GitHubConnection> GitHubConnections=>Set<GitHubConnection>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<RefresherContent> RefresherContents=>Set<RefresherContent>();
 protected override void OnModelCreating(ModelBuilder b){b.Entity<User>(e=>{e.HasIndex(x=>x.Email).IsUnique();e.Property(x=>x.Email).HasMaxLength(320);});b.Entity<MentorLearner>(e=>{e.HasIndex(x=>new{x.LearnerId,x.MentorEmail}).IsUnique();e.HasOne(x=>x.Learner).WithMany().HasForeignKey(x=>x.LearnerId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.MentorUser).WithMany().HasForeignKey(x=>x.MentorUserId).OnDelete(DeleteBehavior.Restrict);});b.Entity<Skill>(e=>{e.Property(x=>x.Title).HasMaxLength(160);e.HasOne(x=>x.Learner).WithMany(x=>x.Skills).HasForeignKey(x=>x.LearnerId);});b.Entity<SkillPrerequisite>().HasKey(x=>new{x.SkillId,x.PrerequisiteSkillId});b.Entity<SkillPrerequisite>().HasOne(x=>x.Skill).WithMany(x=>x.Prerequisites).HasForeignKey(x=>x.SkillId).OnDelete(DeleteBehavior.Restrict);b.Entity<SkillPrerequisite>().HasOne(x=>x.PrerequisiteSkill).WithMany().HasForeignKey(x=>x.PrerequisiteSkillId).OnDelete(DeleteBehavior.Restrict);b.Entity<StudyLog>(e=>{e.HasIndex(x=>new{x.SkillId,x.StudiedAtUtc});e.HasOne(x=>x.Skill).WithMany().HasForeignKey(x=>x.SkillId);});b.Entity<PracticeSignal>(e=>{e.HasIndex(x=>new{x.SkillId,x.OccurredAtUtc});e.HasOne(x=>x.Skill).WithMany().HasForeignKey(x=>x.SkillId);});b.Entity<GitHubConnection>(e=>{e.HasIndex(x=>x.LearnerId).IsUnique();e.HasIndex(x=>x.OAuthState);e.Property(x=>x.GitHubUsername).HasMaxLength(100);e.Property(x=>x.OAuthState).HasMaxLength(120);e.HasOne(x=>x.Learner).WithMany().HasForeignKey(x=>x.LearnerId).OnDelete(DeleteBehavior.Cascade);});b.Entity<Notification>(e=>{e.HasIndex(x=>new{x.LearnerId,x.IsRead,x.CreatedAtUtc});e.HasOne(x=>x.Learner).WithMany().HasForeignKey(x=>x.LearnerId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.Mentor).WithMany().HasForeignKey(x=>x.MentorId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.Skill).WithMany().HasForeignKey(x=>x.SkillId).OnDelete(DeleteBehavior.Restrict);});b.Entity<RefresherContent>(e=>{e.HasIndex(x=>x.SkillId);e.Property(x=>x.Title).HasMaxLength(220);e.Property(x=>x.Url).HasMaxLength(600);e.Property(x=>x.Provider).HasMaxLength(80);e.HasOne(x=>x.Skill).WithMany().HasForeignKey(x=>x.SkillId).OnDelete(DeleteBehavior.Cascade);});}
}
